const core = global.get('core');

return (async () => {
    await core.osc.client.open();
    await core.health.start();

    const directives = core.scheduling.cronSync.rebuildAll(core.db.connection);
    const msgs = directives.map((d) => {
        if (d.toRemoveAllDynamic) return { topic: 'remove-all-dynamic' };
        if (d.toAdd) return { payload: d.toAdd };
        if (d.toRemove) return { payload: d.toRemove };
        return null;
    }).filter(Boolean);

    node.log(`Startup: rebuilding ${msgs.length} cron-plus directive(s)`);
    // Two distinct outputs so downstream 'refresh once' consumers (the cue dropdown,
    // the schedule table) aren't re-triggered once per cron-plus directive - output 1 is
    // the directive array (>=1 msgs) for cron-plus only, output 2 is exactly one trigger
    // msg for anything that just needs to know "startup happened".
    return [msgs, [{ payload: 'startup' }]];
})();

const core = global.get('core');

if (!msg.topic || !msg.topic.startsWith('sched-')) {
    // command-response / status messages from cron-plus itself, not a fire event - ignore
    return null;
}

const scheduleId = Number(msg.topic.replace('sched-', ''));
const schedule = core.db.schedules.getById(core.db.connection, scheduleId);

if (!schedule) {
    node.warn(`No schedule found in DB for ${msg.topic} (deleted since being scheduled?)`);
    return null;
}

if (!core.health.isArmed()) {
    node.warn(`Skipping ${schedule.qlabCueNumber}: QLab not confirmed live (health state: ${core.health.getState()})`);
    return null;
}

return (async () => {
    await core.osc.protocol.playCue(schedule.qlabCueNumber);
    return { payload: `Played ${schedule.qlabCueNumber} (schedule ${scheduleId}: ${schedule.name})` };
})();

const core = global.get('core');
const { nextOccurrences } = core.scheduling.occurrenceCalculator;

const schedules = core.db.schedules.listAll(core.db.connection);

const rows = schedules.map((s) => {
    const cache = core.db.cueCache.getByCueNumber(core.db.connection, s.qlabCueNumber);
    let next = '';
    try {
        const occurrences = nextOccurrences(s, new Date(), 1);
        if (occurrences[0]) next = occurrences[0].toLocaleString();
    } catch (err) {
        next = 'error';
    }
    return {
        ID: s.id,
        Name: s.name,
        Cue: s.qlabCueNumber,
        'Every (s)': s.intervalSeconds,
        Enabled: s.enabled,
        Zones: cache ? cache.zones.join(', ') : '(unknown - not yet cached)',
        'Next Occurrence': next
    };
});

return { payload: rows };

const row = Array.isArray(msg.payload) ? msg.payload[0] : msg.payload;
const id = row && (row.ID ?? row.id);

if (id == null) {
    return null; // deselection - leave the last selection in place rather than clearing it
}

flow.set('selectedScheduleId', Number(id));
return { payload: `Selected: ${row.Name || row.name} (id ${id})` };

const core = global.get('core');

return (async () => {
    const cues = await core.osc.protocol.listCues();
    const audioCues = cues.filter((c) => c.number && c.type === 'Audio');

    // Confirmed against ui_form.js source: dynamic property updates (dropdownOptions,
    // options, label) MUST be wrapped in msg.ui_update - beforeSend() special-cases that
    // key on every incoming message, before the generic datastore fallback runs. A
    // top-level msg.dropdownOptions (my first attempt) is silently ignored.
    // Each option is tagged with which form field it belongs to via `dropdown` (matching
    // the field's `key`), rendered using item-title: 'label', item-value: 'value'
    // (confirmed against the compiled frontend bundle).
    const options = audioCues.map((c) => ({
        dropdown: 'qlabCueNumber',
        label: `${c.number} - ${c.listName || c.name || '(unnamed)'}`,
        value: c.number
    }));

    node.log(`Populated cue dropdown with ${options.length} audio cue(s)`);
    return { ui_update: { dropdownOptions: options } };
})();

const core = global.get('core');
const f = msg.payload;
const editingScheduleId = flow.get('editingScheduleId');
const wasEditing = editingScheduleId != null;

const weekdays = [];
if (f.monday) weekdays.push(1);
if (f.tuesday) weekdays.push(2);
if (f.wednesday) weekdays.push(3);
if (f.thursday) weekdays.push(4);
if (f.friday) weekdays.push(5);
if (f.saturday) weekdays.push(6);
if (f.sunday) weekdays.push(7);

let schedule;
try {
    const validated = core.scheduling.validateSchedule({
        name: f.name,
        qlabCueNumber: f.qlabCueNumber,
        intervalSeconds: Number(f.intervalSeconds),
        startTime: f.startTime || null,
        endTime: f.endTime || null,
        weekdays: weekdays.length ? weekdays : undefined,
        dateRangeStart: f.dateRangeStart || null,
        dateRangeEnd: f.dateRangeEnd || null
    });

    if (wasEditing) {
        schedule = core.db.schedules.update(core.db.connection, editingScheduleId, validated);
        if (!schedule) {
            node.warn(`Schedule ${editingScheduleId} being edited no longer exists - creating a new one instead`);
            schedule = core.db.schedules.create(core.db.connection, validated);
        }
    } else {
        schedule = core.db.schedules.create(core.db.connection, validated);
    }
} catch (err) {
    node.warn(`Add/Edit Schedule rejected: ${err.message}`);
    return null;
}

flow.set('editingScheduleId', null);

const directives = core.scheduling.cronSync.syncOne(core.db.connection, schedule.id);
const cronMsgs = directives.map((d) => {
    if (d.toRemove) return { payload: d.toRemove };
    if (d.toAdd) return { payload: d.toAdd };
    return null;
}).filter(Boolean);

const modeMsg = { payload: `Saved: ${wasEditing ? 'updated' : 'created'} schedule #${schedule.id} (${schedule.name}). Mode: Creating new schedule` };

node.log(`Saved schedule ${schedule.id} (${schedule.name}), synced ${cronMsgs.length} cron-plus directive(s)`);
return [cronMsgs, [{ payload: 'refresh' }], [modeMsg]];

flow.set('selectedScheduleId', null);
flow.set('editingScheduleId', null); // avoid a stale edit-mode flag silently surviving a cleared selection
return [{ payload: '(none selected)' }, { payload: 'Creating new schedule' }];

const core = global.get('core');
const scheduleId = flow.get('selectedScheduleId');

if (scheduleId == null) {
    node.warn('Edit Selected clicked but no schedule is selected - click a row in the table first');
    return null;
}

const s = core.db.schedules.getById(core.db.connection, scheduleId);
if (!s) {
    node.warn(`Selected schedule ${scheduleId} no longer exists`);
    return null;
}

flow.set('editingScheduleId', scheduleId);

// NOTE: confirmed the widget has no 'formValue' property at all (absent from the compiled
// frontend bundle entirely) - pre-fill goes through the SAME msg.payload shape the form
// itself emits on submit, via ui-form's generic datastore fallback (no custom onInput).
const payload = {
    name: s.name,
    qlabCueNumber: s.qlabCueNumber,
    intervalSeconds: s.intervalSeconds,
    startTime: s.startTime || '',
    endTime: s.endTime || '',
    monday: s.weekdays.includes(1),
    tuesday: s.weekdays.includes(2),
    wednesday: s.weekdays.includes(3),
    thursday: s.weekdays.includes(4),
    friday: s.weekdays.includes(5),
    saturday: s.weekdays.includes(6),
    sunday: s.weekdays.includes(7),
    dateRangeStart: s.dateRangeStart || '',
    dateRangeEnd: s.dateRangeEnd || ''
};

node.log(`Loaded schedule ${scheduleId} into the Add/Edit form`);
return [{ payload }, { payload: `Editing schedule #${scheduleId}: ${s.name}` }];

const core = global.get('core');
const scheduleId = flow.get('selectedScheduleId');

if (scheduleId == null) {
    node.warn('Toggle Enabled clicked but no schedule is selected - click a row in the table first');
    return null;
}

const schedule = core.db.schedules.getById(core.db.connection, scheduleId);
if (!schedule) {
    node.warn(`Selected schedule ${scheduleId} no longer exists`);
    return null;
}

core.db.schedules.setEnabled(core.db.connection, scheduleId, !schedule.enabled);
const directives = core.scheduling.cronSync.syncOne(core.db.connection, scheduleId);
const cronMsgs = directives.map((d) => {
    if (d.toRemove) return { payload: d.toRemove };
    if (d.toAdd) return { payload: d.toAdd };
    return null;
}).filter(Boolean);

node.log(`Schedule ${scheduleId} enabled -> ${!schedule.enabled}`);
return [cronMsgs, [{ payload: 'refresh' }]];

const core = global.get('core');
const scheduleId = flow.get('selectedScheduleId');

if (scheduleId == null) {
    node.warn('Play Now clicked but no schedule is selected - click a row in the table first');
    return null;
}

const schedule = core.db.schedules.getById(core.db.connection, scheduleId);
if (!schedule) {
    node.warn(`Selected schedule ${scheduleId} no longer exists`);
    return null;
}

// NOTE: v1 play-now fires directly, bypassing zone collision/wait logic - that composition
// lands in Phase 5 once lib/queue/zoneQueueEngine.js exists (see docs/claude-plan.md).
return (async () => {
    await core.osc.protocol.playCue(schedule.qlabCueNumber);
    return { payload: `Play-now: ${schedule.qlabCueNumber} (${schedule.name})` };
})();
